package store

import (
  "database/sql"
  "errors"
  "fmt"
)

var ErrNotFound = errors.New("user not found")

func (s *Store) FindUser(id string) (*User, error) {
  var u User
  err := s.db.QueryRow(findUserSQL, id).Scan(&u.ID, &u.Name)
  if err != nil {
    if errors.Is(err, sql.ErrNoRows) {
      return nil, fmt.Errorf("find user %s: %v", id, ErrNotFound)
    }
    return nil, fmt.Errorf("scan user: %v", err)
  }
  return &u, nil
}
